package io.github.diodeme.ji.host.sqlite;

import io.github.diodeme.ji.host.HostStore;
import io.github.diodeme.ji.host.HostStoreTck;
import io.github.diodeme.ji.host.PersistentHostStore;
import java.io.IOException;
import java.nio.file.Files;

final class SqliteHostStoreTckTest extends HostStoreTck {
    @Override
    protected HostStore createStore() {
        try {
            return new PersistentHostStore(new SqliteHostStorePersistence(
                    Files.createTempFile("ji-host-tck-", ".db")));
        } catch (IOException exception) {
            throw new IllegalStateException(exception);
        }
    }
}
